export function blockingErrors(results, editedFiles) {
  const filtered = [];

  // Iterate over all report files
  for (const report of results) {
    // Skip if the file was not edited
    if (!editedFiles.has(report.filePath)) {
      continue;
    }

    // Iterate over all messages in the report
    for (const msg of report.messages) {
      // Only include messages with severity 2 (Error)
      if (msg.severity === 2) {
        filtered.push({
          file: report.filePath,
          line: msg.line,
          rule: msg.ruleId ?? '',
          message: msg.message,
        });
      }
    }
  }

  // Sort: by file ascending, then by line ascending
  filtered.sort((a, b) => {
    const fileDiff = a.file.localeCompare(b.file);
    if (fileDiff !== 0) return fileDiff;
    return a.line - b.line;
  });

  return filtered;
}

